#include "test_common.h"
#include "graph_management.h"
static BmsStatus_t count_visit(const BmsHospital_t*h,void*c){(void)h;(*(uint32_t*)c)++;return BMS_STATUS_OK;}
static void test_graph_routes(void){BmsHospitalGraph_t g;BmsHospital_t a=TestHospital(1,"A Hospital"),b=TestHospital(2,"B Hospital"),c=TestHospital(3,"C Hospital");uint32_t d=0,count=0;BmsHospitalId_t nearest=0;ASSERT_STATUS(BMS_STATUS_OK,GraphInitialize(&g));ASSERT_STATUS(BMS_STATUS_OK,GraphAddHospital(&g,&a));ASSERT_STATUS(BMS_STATUS_OK,GraphAddHospital(&g,&b));ASSERT_STATUS(BMS_STATUS_OK,GraphAddHospital(&g,&c));ASSERT_STATUS(BMS_STATUS_OK,GraphAddRoute(&g,1U,2U,5U));ASSERT_STATUS(BMS_STATUS_OK,GraphAddRoute(&g,1U,3U,10U));ASSERT_STATUS(BMS_STATUS_OK,GraphGetRouteDistance(&g,1U,2U,&d));CU_ASSERT_EQUAL(d,5U);ASSERT_STATUS(BMS_STATUS_OK,GraphFindNearestHospital(&g,1U,&nearest,&d));CU_ASSERT_EQUAL(nearest,2U);ASSERT_STATUS(BMS_STATUS_OK,GraphBreadthFirstSearch(&g,1U,count_visit,&count));CU_ASSERT_EQUAL(count,3U);count=0;ASSERT_STATUS(BMS_STATUS_OK,GraphDepthFirstSearch(&g,1U,count_visit,&count));CU_ASSERT_EQUAL(count,3U);ASSERT_STATUS(BMS_STATUS_OK,GraphRemoveRoute(&g,1U,2U));GraphClear(&g);}
void RegisterGraphTests(void){CU_pSuite s=CU_add_suite("Graph",NULL,NULL);CU_add_test(s,"routes BFS DFS nearest",test_graph_routes);}
